import re,heapq
g={}
for a,b,w in re.findall(r'N(\d+) -- N(\d+) weight (\d+)',external_context):
    a,b,w=int(a),int(b),int(w);g.setdefault(a,[]).append((b,w));g.setdefault(b,[]).append((a,w))
d={0:0};h=[(0,0)]
while h:
    x,u=heapq.heappop(h)
    if x>d[u]:continue
    for v,w in g[u]:
        if x+w<d.get(v,1e9):d[v]=x+w;heapq.heappush(h,(x+w,v))
